import 'package:freezed_annotation/freezed_annotation.dart';

part 'alias.freezed.dart';

/// Anonymous per-room identity, generated by the Random User API
/// (e.g. "Montserrat Romero").
@freezed
abstract class Alias with _$Alias {
  const Alias._();

  const factory Alias({
    required String firstName,
    required String lastName,
  }) = _Alias;

  /// "Montserrat Romero" — stored on the member and shown in chats.
  String get displayName => '$firstName $lastName';

  /// ["Montserrat", "Romero"] — the identity card shows one name per line.
  List<String> get displayLines => [firstName, lastName];

  /// "MontserratRomero" — shown as `@MontserratRomero` above chat bubbles.
  String get handle => displayName.replaceAll(_nonHandleChars, '');

  static final RegExp _nonHandleChars = RegExp(r"[\s'’\-.]");
}
